\label{tab:selectivity}
\small
\begin{tabular}{lrrrr}
\toprule
\textbf{Contam.} & \multicolumn{2}{c}{\textbf{Contam.\ Items}} & \multicolumn{2}{c}{\textbf{Non-Contam.\ Items}} \\
\cmidrule(lr){2-3} \cmidrule(lr){4-5}
